function OverseaManageCafeCattyStarRewardPopupCell:RefreshShow(data,index)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    local curStarLevel = component:GetMaidCoffeeCattyStarLevel()
    CfUtils.FillText(self.animRoot,index)
    self:FillReward(data)
    CfUtils.SetActive(self.FinishGroup.gameObject,curStarLevel>=index)
    CfUtils.SetActive(self.TxtUnfinished.gameObject,curStarLevel < index)
end

function OverseaManageCafeCattyStarRewardPopupCell:FillReward(data)
    local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsListLight")
    rewardEnv:FreshBaseUI(data.goods)
end

function OverseaManageCafeCattyStarRewardPopupCell:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

